document.addEventListener("DOMContentLoaded",function(){const l=document.getElementById("postForm"),d=document.getElementById("postList");function c(t){d.innerHTML="",t.forEach((e,o)=>{const s=document.createElement("div");s.classList.add("post-item"),s.innerHTML=`
                <h2>${e.title}</h2>
                <p>${e.content}</p>
                <button onclick="editPost(${o})">Edit</button>
                <button onclick="deletePost(${o})">Delete</button>
            `,d.appendChild(s)})}let n=[];l.addEventListener("submit",function(t){t.preventDefault();const e=document.getElementById("title").value,o=document.getElementById("content").value;e&&o?(n.push({title:e,content:o}),c(n),l.reset()):alert("Please fill in both title and content.")}),window.editPost=function(t){const e=n[t];document.getElementById("title").value=e.title,document.getElementById("content").value=e.content,n.splice(t,1),c(n)},window.deletePost=function(t){n.splice(t,1),c(n)}});
